print(write_file(p, '''def transform(grid):
    # The large filled patterned object is recolored to the color of its matching
    # marker line. Identify the biggest non-background connected component by color.
    from collections import Counter
    H,W=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    def comps(col):
        seen=set(); out=[]
        for r in range(H):
            for c in range(W):
                if grid[r][c]!=col or (r,c) in seen: continue
                seen.add((r,c)); stack=[(r,c)]; comp=[]
                while stack:
                    x,y=stack.pop();comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        z=(x+dx,y+dy)
                        if 0<=z[0]<H and 0<=z[1]<W and z not in seen and grid[z[0]][z[1]]==col:
                            seen.add(z);stack.append(z)
                out.append(comp)
        return out
    # Select the maximal-area dense blob, excluding the one-cell-wide marker(s).
    choices=[]
    for col in set(v for row in grid for v in row)-{bg}:
        for comp in comps(col):
            rs=[x for x,y in comp]; cs=[y for x,y in comp]
            box=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
            if len(comp)>=5 and len(comp)/box>0.45: choices.append((len(comp),col,comp))
    _,src,blob=max(choices)
    # The replacement color is indicated by a one-cell-wide line object.
    lines=[]
    for col in set(v for row in grid for v in row)-{bg,src}:
        for comp in comps(col):
            rs=[x for x,y in comp]; cs=[y for x,y in comp]
            if len(comp)>=3 and (len(set(rs))==1 or len(set(cs))==1): lines.append((len(comp),col))
    dst=max(lines)[1]
    out=[row[:] for row in grid]
    for r,c in blob: out[r][c]=dst
    return out
'''))

